import { describe, expect, it } from 'vitest';
import { QUALITY_PROFILES, applyQuality, qualityProfile, volumeToGain } from '../core/QualitySettings';
import type { QualityTarget } from '../core/QualitySettings';
import type { Renderer } from '../core/Renderer';
import { FEEDBACK_SOUNDS, FeedbackSystem, HAZARD_SOUNDS, detectBounce } from './FeedbackSystem';

const ORIGIN = { x: 0, y: 0.4, z: 0 };

class MixerSpy {
  readonly played: string[] = [];
  readonly volumes: number[] = [];

  play(id: string): boolean {
    this.played.push(id);
    return true;
  }

  setMasterVolume(volume: number): void {
    this.volumes.push(volume);
  }
}

const system = (quality = 'high', audio?: MixerSpy): FeedbackSystem =>
  new FeedbackSystem({ quality, audio, volume: 100, random: () => 0.5 });

describe('FeedbackSystem', () => {
  it('spawns a celebration burst and requests the cup sound when a ball is holed', () => {
    const mixer = new MixerSpy();
    const feedback = system('high', mixer);

    feedback.holed({ x: 1, y: 0.2, z: 2 });

    expect(feedback.emittedFor('holed')).toBeGreaterThan(0);
    expect(feedback.activeParticles).toBe(feedback.emittedFor('holed'));
    expect(mixer.played).toContain(FEEDBACK_SOUNDS.holed);
    expect(feedback.soundRequests(FEEDBACK_SOUNDS.holed)).toBe(1);
    feedback.dispose();
  });

  it('puffs turf and clicks the club on a putt', () => {
    const mixer = new MixerSpy();
    const feedback = system('high', mixer);

    feedback.shot(ORIGIN, 0.8);

    expect(feedback.emittedFor('shot')).toBeGreaterThan(0);
    expect(mixer.played).toEqual([FEEDBACK_SOUNDS.shot]);
  });

  it('plays the sound that matches the hazard kind', () => {
    const mixer = new MixerSpy();
    const feedback = system('high', mixer);

    feedback.hazard(ORIGIN, 'water');
    feedback.hazard(ORIGIN, 'lava');

    expect(mixer.played).toEqual([HAZARD_SOUNDS.water, HAZARD_SOUNDS.lava]);
    expect(feedback.emittedFor('hazard')).toBeGreaterThan(0);
  });

  it('rate limits wall bounces until the cooldown elapses', () => {
    const mixer = new MixerSpy();
    const feedback = system('high', mixer);

    feedback.bounce(ORIGIN, 6);
    feedback.bounce(ORIGIN, 6);
    expect(mixer.played).toHaveLength(1);

    feedback.update(0.1);
    feedback.bounce(ORIGIN, 6);
    expect(mixer.played).toHaveLength(2);
  });

  it('scales bursts with the graphics preset', () => {
    const low = system('low');
    const ultra = system('ultra');

    low.holed(ORIGIN);
    ultra.holed(ORIGIN);

    expect(low.emittedFor('holed')).toBeGreaterThan(0);
    expect(low.emittedFor('holed')).toBeLessThan(ultra.emittedFor('holed'));
  });

  it('keeps live particles inside the preset budget', () => {
    const feedback = system('low');
    for (let burst = 0; burst < 40; burst += 1) feedback.holed(ORIGIN);
    expect(feedback.activeParticles).toBeLessThanOrEqual(QUALITY_PROFILES.low.particleBudget);
  });

  it('moves the mixer when the volume slider changes', () => {
    const mixer = new MixerSpy();
    const feedback = system('high', mixer);
    expect(mixer.volumes).toEqual([1]);

    feedback.setVolume(40);
    expect(feedback.masterVolume).toBeCloseTo(0.4);

    feedback.setVolume(0);
    expect(mixer.volumes).toEqual([1, 0.4, 0]);
  });

  it('switches the active preset', () => {
    const feedback = system('high');
    expect(feedback.quality).toBe('high');
    expect(feedback.setQuality('low').particleBudget).toBe(QUALITY_PROFILES.low.particleBudget);
    expect(feedback.quality).toBe('low');
  });
});

describe('detectBounce', () => {
  it('reports the impact speed when the horizontal direction flips', () => {
    expect(detectBounce({ x: 0, y: 0, z: 4 }, { x: 0, y: 0, z: -3 })).toBeCloseTo(4);
  });

  it('ignores rolling and slow contacts', () => {
    expect(detectBounce({ x: 0, y: 0, z: 4 }, { x: 0, y: 0, z: 3.5 })).toBeUndefined();
    expect(detectBounce({ x: 0, y: 0, z: 0.4 }, { x: 0, y: 0, z: -0.4 })).toBeUndefined();
  });
});

describe('quality settings', () => {
  it('pushes the preset into the renderer', () => {
    const applied: Array<[number, boolean]> = [];
    let ratio = 0;
    const target: QualityTarget = {
      setMaxPixelRatio: (value) => {
        ratio = value;
        return value;
      },
      setShadowsEnabled: (enabled) => applied.push([ratio, enabled]),
    };

    expect(applyQuality(target, 'low')).toBe(QUALITY_PROFILES.low);
    expect(applied).toEqual([[QUALITY_PROFILES.low.maxPixelRatio, false]]);

    applyQuality(target, 'ultra');
    expect(ratio).toBe(QUALITY_PROFILES.ultra.maxPixelRatio);
    expect(applied.at(-1)).toEqual([QUALITY_PROFILES.ultra.maxPixelRatio, true]);
  });

  it('falls back to the shipped default for unknown presets', () => {
    expect(qualityProfile('cinematic')).toBe(QUALITY_PROFILES.high);
    expect(qualityProfile(undefined)).toBe(QUALITY_PROFILES.high);
  });

  it('maps the slider onto mixer gain', () => {
    expect(volumeToGain(80)).toBeCloseTo(0.8);
    expect(volumeToGain(-5)).toBe(0);
    expect(volumeToGain(500)).toBe(1);
  });

  it('keeps core/Renderer compatible with the quality plumbing', () => {
    // Compile-time proof that the real renderer satisfies the structural target.
    const target: QualityTarget | undefined = undefined as Renderer | undefined;
    expect(target).toBeUndefined();
  });
});
