import { describe, expect, it } from 'vitest';
import type { AudioEventDefinition } from './AudioManager';
import { AUDIO_MANIFEST_URL, parseAudioManifest, registerAudioManifest } from './audioManifest';

const MANIFEST = {
  version: 1,
  events: [
    { id: 'hit', url: '/audio/sfx/hit.mp3', category: 'sfx', volume: 0.9, optional: true },
    { id: 'theme', url: '/audio/music/theme.mp3', category: 'music', loop: true },
    { id: 'broken', url: '/audio/sfx/broken.mp3', category: 'nope' },
    { id: 'no-url', category: 'sfx' },
  ],
};

describe('audio manifest', () => {
  it('keeps well formed events and drops the rest', () => {
    const events = parseAudioManifest(MANIFEST);

    expect(events.map((event) => event.id)).toEqual(['hit', 'theme']);
    expect(events[0]?.volume).toBeCloseTo(0.9);
    expect(events[1]?.loop).toBe(true);
    expect(events[1]?.optional).toBe(true);
  });

  it('returns nothing for junk payloads', () => {
    expect(parseAudioManifest(null)).toEqual([]);
    expect(parseAudioManifest({ events: 'nope' })).toEqual([]);
  });

  it('registers the manifest on the mixer', async () => {
    const registered: AudioEventDefinition[] = [];
    const urls: string[] = [];

    const events = await registerAudioManifest(
      { registerMany: (definitions) => registered.push(...definitions) },
      AUDIO_MANIFEST_URL,
      async (url) => {
        urls.push(url);
        return { ok: true, status: 200, json: async () => MANIFEST };
      },
    );

    expect(urls).toEqual([AUDIO_MANIFEST_URL]);
    expect(events).toHaveLength(2);
    expect(registered.map((event) => event.id)).toEqual(['hit', 'theme']);
  });

  it('stays silent when the manifest is missing or unreachable', async () => {
    const sink = {
      registerMany: () => {
        throw new Error('must not register');
      },
    };

    const missing = await registerAudioManifest(sink, AUDIO_MANIFEST_URL, async () => ({
      ok: false,
      status: 404,
      json: async () => ({}),
    }));
    const offline = await registerAudioManifest(sink, AUDIO_MANIFEST_URL, async () => {
      throw new Error('offline');
    });

    expect(missing).toEqual([]);
    expect(offline).toEqual([]);
  });
});
